-- Orders carry what goods cost. They are read by the owner and whoever keeps or checks the
-- books, and written by the owner and an accountant, in the branches they work in (a member
-- limited to some branches sees those branches' warehouses and no others).
CREATE POLICY purchase_orders_select ON public.purchase_orders FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor')
    AND EXISTS (SELECT 1 FROM public.warehouses w WHERE w.tenant_id = purchase_orders.tenant_id AND w.id = purchase_orders.warehouse_id)
  );
--> statement-breakpoint
