-- ── hand-written: what may happen to a purchase document ────────────────────────────────────────
-- The guard of an order and of a goods received note, whoever writes the row, the functions
-- below included. A document starts as a draft; once it has moved on it is never changed, and
-- only a draft is removed. A goods received note is for one submitted order: its supplier and
-- its warehouse are the order's (asked here, with the table owner's rights, because the
-- warehouse does not read orders), and never change. The times on a row are the database's
-- own. Only a session signed in as postgres itself (a migration, or the removal of a synthetic
-- test company) is not held to this.
CREATE FUNCTION app.check_purchase_document() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.tenant_id IS DISTINCT FROM app.tenant_id() THEN
      RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'a submitted order or posted goods received note is never removed' USING ERRCODE = 'SE213';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- A date is a day on the calendar. The two tables share this guard, so their dates are read
  -- from the row as JSON: a column one table lacks cannot be named on NEW.
  IF coalesce(to_jsonb(NEW)->>'order_date', '') ~ 'infinity' OR coalesce(to_jsonb(NEW)->>'expected_on', '') ~ 'infinity'
     OR coalesce(to_jsonb(NEW)->>'receipt_date', '') ~ 'infinity' THEN
    RAISE EXCEPTION 'a date on a purchase document is a day on the calendar' USING ERRCODE = 'SE220';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'a purchase document starts as a draft' USING ERRCODE = 'SE212';
    END IF;
    NEW.created_at := now();
    NEW.updated_at := clock_timestamp();
  ELSE
    IF OLD.status <> 'draft' AND NOT (TG_TABLE_NAME = 'purchase_orders' AND OLD.status = 'submitted' AND NEW.status = 'cancelled') THEN
      RAISE EXCEPTION 'a submitted order or posted goods received note is never changed' USING ERRCODE = 'SE213';
    END IF;
    IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id OR NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at THEN
      RAISE EXCEPTION 'what a purchase document is and who wrote it never change' USING ERRCODE = 'SE213';
    END IF;
    -- Cancelling changes nothing else about the order.
    IF OLD.status = 'submitted' AND (to_jsonb(NEW) - ARRAY['status', 'cancelled_at', 'cancelled_by', 'cancel_reason', 'updated_at', 'updated_by'])
         IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status', 'cancelled_at', 'cancelled_by', 'cancel_reason', 'updated_at', 'updated_by']) THEN
      RAISE EXCEPTION 'a submitted order is cancelled as it stands' USING ERRCODE = 'SE213';
    END IF;
    -- Always later than what anyone read before this change, so a screen opened earlier can tell.
    NEW.updated_at := clock_timestamp();
  END IF;
  IF TG_TABLE_NAME = 'goods_receipts' THEN
    IF TG_OP = 'UPDATE' AND (NEW.order_id <> OLD.order_id OR NEW.supplier_id <> OLD.supplier_id OR NEW.warehouse_id <> OLD.warehouse_id) THEN
      RAISE EXCEPTION 'goods received stay with the order they were written for' USING ERRCODE = 'SE217';
    END IF;
    -- This guard runs before the policies do. So the order is looked for only on behalf of a
    -- member who may receive goods into the warehouse the row names; anyone else is left to the
    -- policies, which refuse them in the same words whether the order is there or not.
    -- The order is held, shared, until the transaction ends: it cannot be cancelled while a
    -- note is being started against it, and a note started while it is being cancelled waits
    -- and is then refused.
    IF TG_OP = 'INSERT' AND app.tenant_role() IN ('owner', 'accountant', 'warehouse_manager')
       AND (app.tenant_branch_ids() IS NULL OR EXISTS (
         SELECT 1 FROM public.warehouses w WHERE w.tenant_id = NEW.tenant_id AND w.id = NEW.warehouse_id AND w.branch_id = ANY (app.tenant_branch_ids()))) THEN
      PERFORM 1 FROM public.purchase_orders o
        WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.order_id AND o.status = 'submitted'
          AND o.supplier_id = NEW.supplier_id AND o.warehouse_id = NEW.warehouse_id
        FOR SHARE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'goods are received against a submitted order, from its supplier, into its warehouse' USING ERRCODE = 'SE217';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_purchase_document() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER purchase_orders_check
  BEFORE INSERT OR UPDATE OR DELETE ON public.purchase_orders
  FOR EACH ROW EXECUTE FUNCTION app.check_purchase_document();
--> statement-breakpoint
ALTER TABLE public.purchase_orders ENABLE ALWAYS TRIGGER purchase_orders_check;
--> statement-breakpoint
CREATE TRIGGER goods_receipts_check
  BEFORE INSERT OR UPDATE OR DELETE ON public.goods_receipts
  FOR EACH ROW EXECUTE FUNCTION app.check_purchase_document();
