-- ── hand-written: the lists the whole app shares ────────────────────────────────────────────────
-- Each added with a function of this step's own, as drizzle/0019_journal_documents.sql says.
-- (Orders and goods received already take a number: PO and GR are among the kinds the product
-- numbers.)

-- The journal of goods received stands with the posted note that names it. It is never
-- reversed: it has no function for a reversal, so one is refused.
CREATE FUNCTION app.journal_backed_goods_receipt(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.goods_receipts r
      WHERE r.tenant_id = p_journal.tenant_id AND r.id = p_journal.source_id AND r.journal_id = p_journal.id AND r.status = 'posted'
        AND r.number = p_journal.document_number AND r.receipt_date = p_journal.journal_date)
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.journal_backed_goods_receipt(public.journals) FROM PUBLIC;
--> statement-breakpoint
