-- ── hand-written: submitting and cancelling an order ────────────────────────────────────────────
-- Not for the app to call: the order's row, held for the rest of the transaction, for a member
-- who may write orders; to anyone else, and outside a member's branches, it does not exist.
CREATE FUNCTION app.hold_purchase_order(p_order uuid) RETURNS public.purchase_orders
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.purchase_orders%ROWTYPE;
BEGIN
  IF v_tenant IS NULL OR app.current_user_id() IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role cannot write purchase orders' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'purchase documents are written in read committed transactions' USING ERRCODE = 'SE219';
  END IF;
  SELECT d.* INTO v_doc FROM public.purchase_orders d WHERE d.tenant_id = v_tenant AND d.id = p_order FOR UPDATE;
  IF NOT FOUND OR (v_scope IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.warehouses w WHERE w.tenant_id = v_tenant AND w.id = v_doc.warehouse_id AND w.branch_id = ANY (v_scope))) THEN
    RAISE EXCEPTION 'no such purchase order in this company' USING ERRCODE = 'SE211';
  END IF;
  RETURN v_doc;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.hold_purchase_order(uuid) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.hold_purchase_order(uuid) FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint
-- Submits a draft order: it must have at least one line, a total that is its lines', and a
-- supplier that is in use. It takes its PO number, for the fiscal year of its date. Returns
-- the number.
CREATE FUNCTION app.submit_purchase_order(p_order uuid) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_doc public.purchase_orders%ROWTYPE := app.hold_purchase_order(p_order);
  v_user uuid := app.current_user_id();
  v_lines integer;
  v_total numeric;
  v_supplier text;
  v_archived timestamptz;
  v_number text;
BEGIN
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft purchase order is submitted' USING ERRCODE = 'SE212';
  END IF;
  SELECT count(*), coalesce(sum(l.amount), 0) INTO v_lines, v_total FROM public.purchase_order_lines l WHERE l.tenant_id = v_doc.tenant_id AND l.order_id = v_doc.id;
  IF v_lines = 0 OR v_doc.total <> v_total THEN
    RAISE EXCEPTION 'an order is submitted with at least one line and a total that is its lines''' USING ERRCODE = 'SE215';
  END IF;
  -- A line was checked against its item's units when it was written. The units may have been
  -- changed since: goods must not come in later by a carton size the item no longer has.
  IF EXISTS (
    SELECT 1 FROM public.purchase_order_lines l
    WHERE l.tenant_id = v_doc.tenant_id AND l.order_id = v_doc.id AND NOT EXISTS (
      SELECT 1 FROM public.items i
      WHERE i.tenant_id = l.tenant_id AND i.id = l.item_id
        AND ((i.base_unit_id = l.unit_id AND l.unit_factor = 1)
          OR EXISTS (SELECT 1 FROM public.item_units u WHERE u.tenant_id = i.tenant_id AND u.item_id = i.id
                       AND u.unit_id = l.unit_id AND u.factor = l.unit_factor)))
  ) THEN
    RAISE EXCEPTION 'an item on the order is no longer ordered in the unit the order names' USING ERRCODE = 'SE222';
  END IF;
  SELECT s.name, s.archived_at INTO v_supplier, v_archived FROM public.suppliers s WHERE s.tenant_id = v_doc.tenant_id AND s.id = v_doc.supplier_id;
  IF v_archived IS NOT NULL THEN
    RAISE EXCEPTION 'the supplier is archived' USING ERRCODE = 'SE221';
  END IF;
  -- Nothing is ordered on a day that has not come: goods could not arrive against it until then.
  -- The day is Pakistan's, as everywhere in the product; not the session's, which a caller can set.
  IF v_doc.order_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE220';
  END IF;
  v_number := app.next_document_number('PO', v_doc.order_date);
  UPDATE public.purchase_orders d SET status = 'submitted', number = v_number, submitted_at = now(), submitted_by = v_user, updated_by = v_user
    WHERE d.tenant_id = v_doc.tenant_id AND d.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_doc.tenant_id, v_user, app.tenant_role(), 'purchase_order.submit', 'purchase_order', v_doc.id,
      jsonb_build_object('number', v_number, 'supplier', v_supplier, 'date', v_doc.order_date, 'lines', v_lines, 'total', v_total::text));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.submit_purchase_order(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.submit_purchase_order(uuid) TO app_runtime;
--> statement-breakpoint
-- Cancels a submitted order that nothing has been received against, with a reason. One with
-- goods received, or with a draft of goods received waiting, stays (SE218).
CREATE FUNCTION app.cancel_purchase_order(p_order uuid, p_reason text) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_doc public.purchase_orders%ROWTYPE := app.hold_purchase_order(p_order);
  v_user uuid := app.current_user_id();
BEGIN
  IF v_doc.status <> 'submitted' THEN
    RAISE EXCEPTION 'only a submitted purchase order is cancelled' USING ERRCODE = 'SE212';
  END IF;
  IF p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 3 AND 300 THEN
    RAISE EXCEPTION 'an order is cancelled with a reason of 3 to 300 characters' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM public.goods_receipts r WHERE r.tenant_id = v_doc.tenant_id AND r.order_id = v_doc.id) THEN
    RAISE EXCEPTION 'an order with goods received, or with a draft of goods received, is not cancelled' USING ERRCODE = 'SE218';
  END IF;
  UPDATE public.purchase_orders d SET status = 'cancelled', cancelled_at = now(), cancelled_by = v_user, cancel_reason = btrim(p_reason), updated_by = v_user
    WHERE d.tenant_id = v_doc.tenant_id AND d.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_doc.tenant_id, v_user, app.tenant_role(), 'purchase_order.cancel', 'purchase_order', v_doc.id,
      jsonb_build_object('number', v_doc.number, 'status', 'submitted'), jsonb_build_object('number', v_doc.number, 'status', 'cancelled', 'reason', btrim(p_reason)));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.cancel_purchase_order(uuid, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.cancel_purchase_order(uuid, text) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: what is left to receive, without what it costs ────────────────────────────────
-- For whoever receives goods: the warehouse does not read orders, which carry cost. The
-- submitted orders with something still to arrive, in the branches the member works in.
CREATE FUNCTION app.orders_to_receive()
  RETURNS TABLE (id uuid, number text, order_date date, expected_on date, supplier_id uuid, supplier_name text, warehouse_id uuid, warehouse_name text, lines_left integer)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
BEGIN
  IF v_tenant IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'auditor', 'warehouse_manager') THEN
    RAISE EXCEPTION 'not allowed to see what is on order' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN QUERY
    SELECT o.id, o.number, o.order_date, o.expected_on, o.supplier_id, s.name, o.warehouse_id, w.name, x.lines_left::integer
    FROM public.purchase_orders o
    JOIN public.suppliers s ON s.tenant_id = o.tenant_id AND s.id = o.supplier_id
    JOIN public.warehouses w ON w.tenant_id = o.tenant_id AND w.id = o.warehouse_id
    CROSS JOIN LATERAL (
      SELECT count(*) AS lines_left FROM public.purchase_order_lines l
      WHERE l.tenant_id = o.tenant_id AND l.order_id = o.id
        AND l.quantity > coalesce((
          SELECT sum(g.quantity) FROM public.goods_receipt_lines g
          JOIN public.goods_receipts r ON r.tenant_id = g.tenant_id AND r.id = g.receipt_id
          WHERE g.tenant_id = l.tenant_id AND g.order_line_id = l.id AND r.status = 'posted'), 0)
    ) x
    WHERE o.tenant_id = v_tenant AND o.status = 'submitted' AND x.lines_left > 0
      AND (v_scope IS NULL OR w.branch_id = ANY (v_scope))
    ORDER BY coalesce(o.expected_on, o.order_date), o.number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.orders_to_receive() FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.orders_to_receive() TO app_runtime;
--> statement-breakpoint
-- The lines of one submitted order with how much has arrived on posted goods received notes.
-- Nothing for an order the member may not receive against.
CREATE FUNCTION app.order_lines_to_receive(p_order uuid)
  RETURNS TABLE (line_id uuid, line_no integer, item_id uuid, item_code text, description text, unit_code text, unit_factor numeric, ordered numeric, received numeric)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
BEGIN
  IF v_tenant IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'auditor', 'warehouse_manager') OR NOT EXISTS (
    SELECT 1 FROM public.purchase_orders o
    JOIN public.warehouses w ON w.tenant_id = o.tenant_id AND w.id = o.warehouse_id
    WHERE o.tenant_id = v_tenant AND o.id = p_order AND o.status = 'submitted' AND (v_scope IS NULL OR w.branch_id = ANY (v_scope))
  ) THEN
    RETURN;
  END IF;
  RETURN QUERY
    SELECT l.id, l.line_no, l.item_id, i.code, l.description, u.code, l.unit_factor, l.quantity,
      coalesce((
        SELECT sum(g.quantity) FROM public.goods_receipt_lines g
        JOIN public.goods_receipts r ON r.tenant_id = g.tenant_id AND r.id = g.receipt_id
        WHERE g.tenant_id = l.tenant_id AND g.order_line_id = l.id AND r.status = 'posted'), 0)
    FROM public.purchase_order_lines l
    JOIN public.items i ON i.tenant_id = l.tenant_id AND i.id = l.item_id
    JOIN public.units u ON u.tenant_id = l.tenant_id AND u.id = l.unit_id
    WHERE l.tenant_id = v_tenant AND l.order_id = p_order
    ORDER BY l.line_no;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.order_lines_to_receive(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.order_lines_to_receive(uuid) TO app_runtime;
--> statement-breakpoint
-- One order as whoever receives against it sees it: its number, its dates, its supplier and its
-- warehouse; no cost. Any order that was submitted, cancelled or not, with all of it arrived or
-- not, so that a goods received note can always name its order. Nothing for a draft, or for an
-- order the member may not receive against.
CREATE FUNCTION app.order_to_receive(p_order uuid)
  RETURNS TABLE (id uuid, number text, status text, order_date date, expected_on date, supplier_id uuid, supplier_name text, warehouse_id uuid, warehouse_name text)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
BEGIN
  IF v_tenant IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'auditor', 'warehouse_manager') THEN
    RETURN;
  END IF;
  RETURN QUERY
    SELECT o.id, o.number, o.status, o.order_date, o.expected_on, o.supplier_id, s.name, o.warehouse_id, w.name
    FROM public.purchase_orders o
    JOIN public.suppliers s ON s.tenant_id = o.tenant_id AND s.id = o.supplier_id
    JOIN public.warehouses w ON w.tenant_id = o.tenant_id AND w.id = o.warehouse_id
    WHERE o.tenant_id = v_tenant AND o.id = p_order AND o.status <> 'draft'
      AND (v_scope IS NULL OR w.branch_id = ANY (v_scope));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.order_to_receive(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.order_to_receive(uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: posting goods received ────────────────────────────────────────────────────────
-- One act of the database, whole or not at all. The note and its order are held, so two notes
-- for one order take their turn. Each line is checked against what is left of its order line;
-- the goods come into the order's warehouse at the order's cost (the quantity at the cost of
-- one, to the paisa); the note takes its GR number; and the journal is posted: debit Stock in
-- trade, credit Goods received not invoiced.
--
-- The owner, an accountant and the warehouse post one. Refused: more than is left of the order
-- (SE216), an order that is not submitted (SE217), a date before the order's or that has not
-- come (SE217, SE220), a closed period.
CREATE FUNCTION app.post_goods_receipt(p_receipt uuid) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.goods_receipts%ROWTYPE;
  v_order public.purchase_orders%ROWTYPE;
  v_branch uuid;
  v_warehouse text;
  v_supplier text;
  v_line record;
  v_value numeric;
  v_total numeric := 0;
  v_lines integer := 0;
  v_number text;
  v_journal uuid;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'warehouse_manager') THEN
    RAISE EXCEPTION 'this role cannot post goods received' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'purchase documents are written in read committed transactions' USING ERRCODE = 'SE219';
  END IF;
  SELECT d.* INTO v_doc FROM public.goods_receipts d WHERE d.tenant_id = v_tenant AND d.id = p_receipt FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such goods received note in this company' USING ERRCODE = 'SE211';
  END IF;
  SELECT w.branch_id, w.name INTO v_branch, v_warehouse FROM public.warehouses w WHERE w.tenant_id = v_tenant AND w.id = v_doc.warehouse_id;
  IF v_scope IS NOT NULL AND NOT (v_branch = ANY (v_scope)) THEN
    RAISE EXCEPTION 'no such goods received note in this company' USING ERRCODE = 'SE211';
  END IF;
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft goods received note is posted' USING ERRCODE = 'SE212';
  END IF;
  -- The order is held until the transaction ends: its goods received notes take their turn,
  -- and it cannot be cancelled meanwhile.
  SELECT o.* INTO v_order FROM public.purchase_orders o WHERE o.tenant_id = v_tenant AND o.id = v_doc.order_id FOR UPDATE;
  IF NOT FOUND OR v_order.status <> 'submitted' OR v_order.supplier_id <> v_doc.supplier_id OR v_order.warehouse_id <> v_doc.warehouse_id THEN
    RAISE EXCEPTION 'goods are received against a submitted order, from its supplier, into its warehouse' USING ERRCODE = 'SE217';
  END IF;
  IF v_doc.receipt_date < v_order.order_date THEN
    RAISE EXCEPTION 'goods are received on or after the day they were ordered' USING ERRCODE = 'SE217';
  END IF;
  -- Nothing is recorded before it happens. The day is Pakistan's, as everywhere in the product
  -- until a company can choose its own time zone; not the session's, which a caller can set.
  IF v_doc.receipt_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE220';
  END IF;
  PERFORM app.require_open_period(v_tenant, v_doc.receipt_date);
  SELECT s.name INTO v_supplier FROM public.suppliers s WHERE s.tenant_id = v_tenant AND s.id = v_doc.supplier_id;

  -- Every balance this note touches is held first, item by item, as for every stock document.
  INSERT INTO public.stock_balances (tenant_id, item_id, warehouse_id)
    SELECT DISTINCT v_tenant, l.item_id, v_doc.warehouse_id
    FROM public.goods_receipt_lines l
    WHERE l.tenant_id = v_tenant AND l.receipt_id = v_doc.id
    ORDER BY l.item_id
    ON CONFLICT (tenant_id, item_id, warehouse_id) DO NOTHING;
  PERFORM 1 FROM public.stock_balances b
    WHERE b.tenant_id = v_tenant AND b.warehouse_id = v_doc.warehouse_id
      AND b.item_id IN (SELECT l.item_id FROM public.goods_receipt_lines l WHERE l.tenant_id = v_tenant AND l.receipt_id = v_doc.id)
    ORDER BY b.item_id
    FOR UPDATE;

  v_number := app.next_document_number('GR', v_doc.receipt_date);
  FOR v_line IN
    SELECT l.id, l.item_id, l.quantity, l.base_quantity, l.unit_factor, i.code,
           o.quantity AS ordered, o.unit_cost, o.item_id AS ordered_item, o.unit_factor AS ordered_factor,
           coalesce((
             SELECT sum(g.quantity) FROM public.goods_receipt_lines g
             JOIN public.goods_receipts r ON r.tenant_id = g.tenant_id AND r.id = g.receipt_id
             WHERE g.tenant_id = v_tenant AND g.order_line_id = o.id AND r.status = 'posted'), 0) AS received
    FROM public.goods_receipt_lines l
    JOIN public.purchase_order_lines o ON o.tenant_id = l.tenant_id AND o.id = l.order_line_id AND o.order_id = v_order.id
    JOIN public.items i ON i.tenant_id = l.tenant_id AND i.id = l.item_id
    WHERE l.tenant_id = v_tenant AND l.receipt_id = v_doc.id
    ORDER BY l.item_id, l.line_no
  LOOP
    IF v_line.item_id <> v_line.ordered_item OR v_line.unit_factor <> v_line.ordered_factor THEN
      RAISE EXCEPTION 'a line of goods received is a line of its order, in the unit it was ordered in' USING ERRCODE = 'SE214';
    END IF;
    IF v_line.received + v_line.quantity > v_line.ordered THEN
      RAISE EXCEPTION 'more of % received than is left of the order: % ordered, % already received, % on this note',
        v_line.code, v_line.ordered, v_line.received, v_line.quantity USING ERRCODE = 'SE216';
    END IF;
    v_value := round(v_line.quantity * v_line.unit_cost, 2);
    PERFORM app.move_stock(v_tenant, v_user, v_line.item_id, v_doc.warehouse_id, v_doc.receipt_date, v_line.base_quantity, v_value, 'goods_receipt', v_doc.id, v_line.id);
    v_total := v_total + v_value;
    v_lines := v_lines + 1;
  END LOOP;
  -- Every line was one of the order's (the lines' guard says so when each is written; asked again here).
  IF v_lines = 0 OR v_lines <> (SELECT count(*) FROM public.goods_receipt_lines l WHERE l.tenant_id = v_tenant AND l.receipt_id = v_doc.id) THEN
    RAISE EXCEPTION 'goods received need at least one line, each a line of the order' USING ERRCODE = 'SE214';
  END IF;

  v_journal := app.post_stock_journal(v_tenant, v_user, v_role, v_doc.receipt_date, 'goods_receipt', v_doc.id, v_number,
    'Goods received from ' || v_supplier || ' against ' || v_order.number, v_branch, 'grni', v_total, 0);
  UPDATE public.goods_receipts d SET status = 'posted', number = v_number, journal_id = v_journal, posted_at = now(), posted_by = v_user, updated_by = v_user
    WHERE d.tenant_id = v_tenant AND d.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'goods_receipt.post', 'goods_receipt', v_doc.id,
      jsonb_build_object('number', v_number, 'order', v_order.number, 'supplier', v_supplier, 'date', v_doc.receipt_date, 'warehouse', v_warehouse, 'lines', v_lines, 'journalId', v_journal));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.post_goods_receipt(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.post_goods_receipt(uuid) TO app_runtime;
